        revert("deprecated");
    }

    function sync(address bep20Addr, uint64 expireTime) public payable returns (bool) {
        revert("deprecated");
    }

    function updateParam(string calldata key, bytes calldata value) external override onlyGov {
        revert("deprecated");
    }

    function queryRequiredLockAmountForBind(string memory symbol) public view returns (uint256) {
        bytes32 bep2Symbol;
        assembly {
            bep2Symbol := mload(add(symbol, 32))
        }
        BindSynPackage memory bindRequest = bindPackageRecord[bep2Symbol];
        if (bindRequest.contractAddr == address(0x00)) {
            return 0;
        }
        uint256 tokenHubBalance = IBEP20(bindRequest.contractAddr).balanceOf(TOKEN_HUB_ADDR);
        uint256 requiredBalance = bindRequest.totalSupply.sub(bindRequest.peggyAmount);
        return requiredBalance.sub(tokenHubBalance);
    }
}

contracts/extension/BSCValidatorSetTool..content:
pragma solidity 0.6.4;

import "../lib/0.6.x/RLPDecode.sol";
import "../lib/0.6.x/Memory.sol";

contract BSCValidatorSetTool {
    bytes public constant INIT_VALIDATORSET_BYTES =
        hex"f84580f842f840949fb29aac15b9a4b7f17c3385939b007540f4d791949fb29aac15b9a4b7f17c3385939b007540f4d791949fb29aac15b9a4b7f17c3385939b007540f4d79164";

    using RLPDecode for *;

    struct Validator {
        address consensusAddress;
        address payable feeAddress;
        address BBCFeeAddress;
        uint64 votingPower;
    }

    struct IbcValidatorSetPackage {
        uint8 packageType;
        Validator[] validatorSet;
    }

    function init() external pure {
        bool valid = decodeValidatorSetSynPackage(INIT_VALIDATORSET_BYTES);
        require(valid, "failed to init");
    }

    function decodeValidatorSetSynPackage(bytes memory msgBytes) internal pure returns (bool) {
        IbcValidatorSetPackage memory validatorSetPkg;

        RLPDecode.Iterator memory iter = msgBytes.toRLPItem().iterator();
        bool success = false;
        uint256 idx = 0;
        while (iter.hasNext()) {
            if (idx == 0) {
                validatorSetPkg.packageType = uint8(iter.next().toUint());
            } else if (idx == 1) {
                RLPDecode.RLPItem[] memory items = iter.next().toList();
                validatorSetPkg.validatorSet = new Validator[](items.length);
                for (uint256 j = 0; j < items.length; ++j) {
                    (Validator memory val, bool ok) = decodeValidator(items[j]);
                    if (!ok) {
                        return false;
                    }
                    validatorSetPkg.validatorSet[j] = val;
                }
                success = true;
            } else {
                break;
            }
            ++idx;
        }
        return success;
    }

    function decodeValidator(RLPDecode.RLPItem memory itemValidator) internal pure returns (Validator memory, bool) {
        Validator memory validator;
        RLPDecode.Iterator memory iter = itemValidator.iterator();
        bool success = false;
        uint256 idx = 0;
        while (iter.hasNext()) {
            if (idx == 0) {
                validator.consensusAddress = iter.next().toAddress();
            } else if (idx == 1) {
                validator.feeAddress = address(uint160(iter.next().toAddress()));
            } else if (idx == 2) {
                validator.BBCFeeAddress = iter.next().toAddress();
            } else if (idx == 3) {
                validator.votingPower = uint64(iter.next().toUint());
                success = true;
            } else {
                break;
            }
            ++idx;
        }
        return (validator, success);
    }

    // | type   | relayFee   |package  |
    // | 1 byte | 32 bytes   | bytes    |
    function decodePayloadHeader(bytes memory payload) public pure returns (bool, uint8, uint256, bytes memory) {
        if (payload.length < 33) {
            return (false, 0, 0, new bytes(0));
        }

        uint256 ptr;
        assembly {
            ptr := payload
        }

        uint8 packageType;
        ptr += 1;
        assembly {
            packageType := mload(ptr)
        }

        uint256 relayFee;
        ptr += 32;
        assembly {
            relayFee := mload(ptr)
        }

        ptr += 32;
        bytes memory msgBytes = new bytes(payload.length - 33);
        (uint256 dst,) = Memory.fromBytes(msgBytes);
        Memory.copy(ptr, dst, payload.length - 33);

        return (true, packageType, relayFee, msgBytes);
    }
}

contracts/GovHub.sol.content:
pragma solidity 0.6.4;

import "./System.sol";
import "./interface/0.6.x/IParamSubscriber.sol";
import "./interface/0.6.x/IApplication.sol";

contract GovHub is System, IApplication {
    uint32 public constant ERROR_TARGET_NOT_CONTRACT = 101;
    uint32 public constant ERROR_TARGET_CONTRACT_FAIL = 102;

    event failReasonWithStr(string message);
    event failReasonWithBytes(bytes message);
    event paramChange(string key, bytes value);  // @dev deprecated

    struct ParamChangePackage {
        string key;
        bytes value;
        address target;
    }

    function handleSynPackage(
        uint8,
        bytes calldata msgBytes
    ) external override onlyCrossChainContract returns (bytes memory responsePayload) {
        revert("deprecated");
    }

    // should not happen
    function handleAckPackage(uint8, bytes calldata) external override onlyCrossChainContract {
        revert("deprecated");
    }

    // should not happen
    function handleFailAckPackage(uint8, bytes calldata) external override onlyCrossChainContract {
        revert("deprecated");
    }

    function updateParam(string calldata key, bytes calldata value, address target) external onlyGovernorTimelock {
        ParamChangePackage memory proposal = ParamChangePackage(key, value, target);
        notifyUpdates(proposal);
    }

    function notifyUpdates(ParamChangePackage memory proposal) internal returns (uint32) {
        if (!isContract(proposal.target)) {
            emit failReasonWithStr("the target is not a contract");
            return ERROR_TARGET_NOT_CONTRACT;
        }
        try IParamSubscriber(proposal.target).updateParam(proposal.key, proposal.value) { }
        catch Error(string memory reason) {
            emit failReasonWithStr(reason);
            return ERROR_TARGET_CONTRACT_FAIL;
        } catch (bytes memory lowLevelData) {
            emit failReasonWithBytes(lowLevelData);
            return ERROR_TARGET_CONTRACT_FAIL;
        }
        return CODE_OK;
    }
}

